{
  "schemaVersion": "0.2",
  "slug": "empty-state",
  "name": "EmptyState",
  "status": "experimental",
  "purpose": "Communicates an empty data set and optionally prompts the next action.",
  "scenarios": [
    "No search results",
    "Empty inbox",
    "No connected accounts"
  ],
  "props": {
    "title": {
      "type": "string",
      "required": true,
      "description": "Primary message."
    },
    "description": {
      "type": "string",
      "required": false,
      "description": "Supporting message."
    },
    "action": {
      "type": "node",
      "required": false,
      "description": "Optional action element."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Empty state displayed."
    }
  ],
  "composition": {
    "allowedParents": [
      "page",
      "card",
      "table"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for loading states.",
    "Do not blame the user."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Focus moves to the action if present.",
    "labeling": "Title is the accessible message.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Centered block with max width.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Max width 24rem.",
      "large": "Max width 24rem."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "empty-state",
    "states": [
      "default"
    ],
    "intents": [
      "prompt-first-action"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface EmptyStateProps {
  title: string
  description?: string
  action?: ReactNode
  className?: string
}

export function EmptyState({ title, description, action, className }: EmptyStateProps) {
  const classes = ['cu-empty-state', className].filter(Boolean).join(' ')
  return (
    <div className={classes} data-ai-role="empty-state" data-ai-state="default" data-ai-intent="prompt-first-action" role="status">
      <div className="cu-empty-state__mark" aria-hidden="true" />
      <div className="cu-empty-state__title">{title}</div>
      {description ? <div className="cu-empty-state__description">{description}</div> : null}
      {action ? <div className="cu-empty-state__action">{action}</div> : null}
    </div>
  )
}

.cu-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-6, var(--cu-space-3));
  padding-inline: var(--cu-space-5, var(--cu-space-3));
  text-align: center;
  color: var(--cu-color-fg-default);
}

.cu-empty-state__mark {
  inline-size: 3rem;
  block-size: 3rem;
  border-radius: var(--cu-radius-lg);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--cu-color-fg-muted, var(--cu-color-fg-default)) 10%, transparent) 0%,
      transparent 62%
    ),
    var(--cu-color-background-elevated, var(--cu-color-background-default));
  box-shadow: var(--cu-shadow-sm);
}

.cu-empty-state__title {
  font-size: var(--cu-typography-size-heading-3, 1.125rem);
  font-weight: var(--cu-typography-weight-semibold, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.022em);
  line-height: var(--cu-typography-line-height-snug, 1.25);
}

.cu-empty-state__description {
  max-inline-size: 28rem;
  font-size: var(--cu-typography-size-body, 0.9375rem);
  line-height: var(--cu-typography-line-height-body, 1.5);
  color: var(--cu-color-fg-muted, var(--cu-color-fg-default));
}

.cu-empty-state__action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--cu-space-2);
  margin-block-start: var(--cu-space-3);
  inline-size: min(100%, 22rem);
}

.cu-empty-state__action .cu-upload {
  inline-size: 100%;
}

.cu-empty-state__action .cu-upload__dropzone {
  inline-size: 100%;
}
